styles:
@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  color-scheme: light;
  font-family: 'Segoe UI Variable Text', 'Segoe UI', 'Avenir Next', sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  --paper: #f3eee2;
  --paper-raised: #fbf7ee;
  --paper-deep: #e5dece;
  --ink: #1c252a;
  --ink-soft: #4e575b;
  --line: #bcb6aa;
  --line-strong: #77756f;
  --cobalt: #1746c6;
  --cobalt-deep: #10338f;
  --vermilion: #b93722;
  --vermilion-deep: #8e291a;
  --site-width: 76rem;
  --page-gutter: clamp(1.25rem, 3.5vw, 3.5rem);
  --column-gap: clamp(1rem, 2.5vw, 2rem);
  --section-space: clamp(3rem, 6vw, 5rem);
  --z-header: 10;
  --z-skip: 20;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; background: var(--paper); }
body { min-inline-size: 0; margin: 0; color: var(--ink); background: var(--paper); font-size: 1rem; line-height: 1.6; }
::selection { background: var(--cobalt); color: #fff; }
a { color: inherit; text-decoration: none; }
button { color: inherit; font: inherit; }
a, button, summary { -webkit-tap-highlight-color: transparent; }
:where(a, button, summary, [tabindex]):focus-visible { outline: 3px solid var(--vermilion); outline-offset: 4px; }
h1, h2, h3, h4, p { margin-block: 0; }
h1, h2, h3 { line-height: 1.15; letter-spacing: -0.035em; text-wrap: balance; }
h2, h3, h4 { font-weight: 700; }
h4 { line-height: 1.4; }
p { text-wrap: pretty; }
p, h1, h2, h3, h4, a { overflow-wrap: anywhere; }
figure, dl { margin: 0; }
ul, ol { padding: 0; margin: 0; }
svg { display: block; flex-shrink: 0; }
img { display: block; max-inline-size: 100%; block-size: auto; }
:where(section[id], article[id], #capabilities) { scroll-margin-block-start: 6rem; }
.site-shell { isolation: isolate; }
.atlas-grid, .page-width {
  inline-size: min(calc(100% - var(--page-gutter) * 2), var(--site-width));
  margin-inline: auto;
}
.atlas-grid { display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); gap: var(--column-gap); }
.atlas-grid > *, .case-study__body > * { min-inline-size: 0; }
.skip-link { position: fixed; z-index: var(--z-skip); top: 0.75rem; left: 0.75rem; padding: 0.75rem 1rem; background: var(--ink); color: var(--paper-raised); font-weight: 700; translate: 0 -200%; }
.skip-link:focus { translate: 0; }
.site-header { position: sticky; z-index: var(--z-header); top: 0; border-block-end: 1px solid var(--line); background: var(--paper); }
.navigation { min-block-size: 4.75rem; align-items: center; }
.navigation__brand { display: inline-flex; grid-column: 1 / 5; align-items: center; gap: 0.7rem; inline-size: fit-content; min-block-size: 2.75rem; }
.navigation__signature { inline-size: 0.25rem; block-size: 2.3rem; background: linear-gradient(to bottom, var(--cobalt) 0 76%, var(--vermilion) 76% 100%); }
.navigation__wordmark { display: grid; gap: 0.15rem; line-height: 1; }
.navigation__given { color: var(--cobalt-deep); font-size: 0.65rem; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; }
.navigation__family { font-family: Georgia, 'Times New Roman', serif; font-size: 1.05rem; font-weight: 600; letter-spacing: -0.025em; }
.navigation__desktop { display: flex; grid-column: 5 / -1; align-items: center; justify-content: flex-end; gap: 1.75rem; }
.navigation__links { display: flex; gap: clamp(1rem, 2vw, 1.8rem); list-style: none; }
.navigation__links a { display: inline-flex; align-items: center; min-block-size: 2.75rem; font-size: 0.85rem; color: var(--ink-soft); white-space: nowrap; }
.navigation__links a:hover { color: var(--cobalt-deep); text-decoration: underline; text-underline-offset: 0.3em; }
.language-link { display: inline-flex; min-block-size: 2.75rem; min-inline-size: 3.5rem; align-items: center; justify-content: center; gap: 0.4rem; border: 1px solid var(--line-strong); font-size: 0.8rem; font-weight: 700; }
.language-link:hover { background: var(--paper-deep); }
.navigation__mobile { display: none; grid-column: 9 / -1; justify-self: end; }
.navigation__mobile summary { display: flex; align-items: center; gap: 0.5rem; padding: 0.5rem 0.75rem; min-block-size: 2.75rem; border: 1px solid var(--line-strong); cursor: pointer; font-size: 0.85rem; list-style: none; }
.navigation__mobile summary::-webkit-details-marker { display: none; }
.navigation__mobile-panel { position: absolute; top: calc(100% + 1px); right: var(--page-gutter); inline-size: min(23rem, calc(100% - var(--page-gutter) * 2)); max-block-size: calc(100dvh - 100% - 1px); overflow-y: auto; overscroll-behavior: contain; padding: 1rem; border: 1px solid var(--line-strong); background: var(--paper-raised); }
.navigation__mobile-panel ul { list-style: none; }
.navigation__mobile-panel li + li { border-block-start: 1px solid var(--line); }
.navigation__mobile-panel a:not(.language-link) { display: flex; align-items: center; min-block-size: 3rem; font-weight: 600; }
.navigation__mobile-panel .language-link { margin-block-start: 0.75rem; }
.eyebrow { display: flex; align-items: center; gap: 0.75rem; color: var(--cobalt-deep); font-size: 0.75rem; font-weight: 700; letter-spacing: 0.075em; line-height: 1.4; text-transform: uppercase; }
.eyebrow > span { color: var(--vermilion-deep); font-variant-numeric: tabular-nums; }
.hero { padding-block: clamp(2.5rem, 5vw, 4.5rem); }
.hero__layout { align-items: center; }
.hero__copy { grid-column: 1 / 8; }
.hero__copy h1 { max-inline-size: 13ch; margin-block: 1.25rem; font-family: Georgia, 'Times New Roman', serif; font-size: clamp(3rem, 5.8vw, 5.5rem); font-weight: 500; letter-spacing: -0.04em; line-height: 1.02; }
.hero__subtitle { max-inline-size: 32ch; margin-block-end: 1rem; font-size: clamp(1.25rem, 2vw, 1.6rem); line-height: 1.35; }
.hero__description { max-inline-size: 54ch; color: var(--ink-soft); font-size: 1.05rem; }
.hero__actions { display: flex; flex-wrap: wrap; gap: 0.75rem; margin-block-start: 1.75rem; }
.action-link { display: inline-flex; align-items: center; justify-content: center; gap: 0.75rem; padding: 0.8rem 1.3rem; min-block-size: 3rem; border: 1px solid var(--line-strong); font-size: 0.9rem; font-weight: 650; line-height: 1.3; transition: background-color 150ms ease; }
.action-link--primary { border-color: var(--cobalt); color: #fff; background: var(--cobalt); }
.action-link--primary:hover { background: var(--cobalt-deep); border-color: var(--cobalt-deep); }
.action-link--secondary:hover { background: var(--paper-deep); }
.text-link { display: inline-flex; align-items: center; gap: 0.5rem; min-block-size: 2.75rem; color: var(--cobalt-deep); font-size: 0.9rem; font-weight: 600; }
.text-link:hover { text-decoration: underline; text-underline-offset: 0.25em; }
.hero__contact { margin-block-start: 0.5rem; font-size: 0.85rem; }
.hero__sectors { grid-column: 9 / -1; padding-inline-start: 1.75rem; border-inline-start: 1px solid var(--line-strong); }
.hero__career { font-family: Georgia, 'Times New Roman', serif; font-size: 2rem; line-height: 1.2; }
.hero__career-description { margin-block: 0.75rem 1.75rem; color: var(--ink-soft); font-size: 0.95rem; }
.hero__sectors-title { font-size: 0.75rem; font-weight: 700; color: var(--cobalt-deep); text-transform: uppercase; letter-spacing: 0.05em; }
.hero__sectors-list { display: flex; flex-wrap: wrap; gap: 0.25rem 1rem; margin-block: 0.75rem 1rem; list-style: none; font-size: 0.9rem; }
.hero__sectors-list li::before { content: '·'; color: var(--vermilion); margin-inline-end: 0.35rem; }
.section-shell { padding-block: var(--section-space); border-block-start: 1px solid var(--line); }
.section-heading { margin-block-end: 2rem; }
.section-heading h2 { font-size: clamp(2rem, 3.5vw, 3rem); margin-block-start: 0.75rem; max-inline-size: 20ch; }
.section-heading > p:not(.eyebrow) { color: var(--ink-soft); max-inline-size: 44ch; margin-block-start: 1rem; }
.section-heading--inline { display: flex; justify-content: space-between; align-items: flex-end; gap: 2rem; }
.section-heading--inline > p { max-inline-size: 35ch; font-size: 1rem; }
.case-study { padding-block: 2rem 1rem; border-block-start: 1px solid var(--line-strong); }
.case-study + .case-study { margin-block-start: 2.5rem; }
.case-study__heading { margin-block-end: 1.75rem; }
.case-study__heading h3 { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.5rem 1.5rem; margin-block-start: 0.5rem; font-size: clamp(2rem, 3vw, 2.5rem); }
.case-study__heading h3 span { font-size: 1.1rem; font-weight: 400; letter-spacing: 0; color: var(--ink-soft); }
.case-study__body { display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr); gap: 2.5rem; align-items: start; }
.case-study__image-link { position: relative; display: block; border: 1px solid var(--line); background: #fff; }
.case-study__image-link img { inline-size: 100%; }
.case-study__image-link > span { position: absolute; inset-inline-end: 0.5rem; inset-block-end: 0.5rem; display: flex; align-items: center; gap: 0.4rem; padding: 0.4rem 0.6rem; background: var(--ink); color: #fff; font-size: 0.75rem; line-height: 1.3; }
.case-study__image-link:hover { outline: 2px solid var(--cobalt); outline-offset: 2px; }
.case-study__figure figcaption { margin-block-start: 0.65rem; color: var(--ink-soft); font-size: 0.8rem; line-height: 1.5; }
.case-study__copy { display: grid; gap: 1.25rem; }
.case-study__copy h4 { margin-block-end: 0.4rem; font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.06em; color: var(--ink-soft); }
.case-study__copy p { font-size: 1rem; line-height: 1.55; }
.case-study__result { border-inline-start: 2px solid var(--cobalt); padding-inline-start: 1rem; }
.case-study__result h4 { color: var(--cobalt-deep); }
.case-study__disclosure { margin-block-start: 1.5rem; border-block-start: 1px solid var(--line); padding-block: 0.25rem; }
.case-study__disclosure summary, .capabilities summary { display: flex; align-items: center; justify-content: space-between; gap: 1rem; min-block-size: 3rem; cursor: pointer; list-style: none; font-size: 0.95rem; font-weight: 650; }
.case-study__disclosure summary::-webkit-details-marker, .capabilities summary::-webkit-details-marker { display: none; }
details[open] > summary svg { rotate: 180deg; }
.case-study__disclosure summary:hover, .capabilities summary:hover { color: var(--cobalt-deep); }
.case-study__decisions { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 2rem; margin-block: 1rem 1.5rem; }
.case-study__decisions h4 { margin-block-end: 0.5rem; font-size: 1rem; }
.case-study__decisions p, .case-study__scope { color: var(--ink-soft); font-size: 0.95rem; }
.case-study__scope { max-inline-size: 75ch; margin-block-end: 0.5rem; }
.other-projects { margin-block-start: 3rem; }
.other-projects > h3 { font-size: 1.5rem; margin-block-end: 1rem; }
.other-project { display: grid; grid-template-columns: minmax(9rem, 1fr) minmax(0, 2.5fr) minmax(8rem, auto); gap: 1.5rem; align-items: start; padding-block: 1.25rem; border-block-start: 1px solid var(--line); }
.other-project h4 { font-size: 1.05rem; }
.other-project > p { font-size: 0.95rem; color: var(--ink-soft); }
.other-project__domain { color: var(--ink-soft); font-size: 0.8rem; margin-block-start: 0.2rem; }
.other-project > .text-link { justify-self: end; min-block-size: 2.75rem; }
.project-status { justify-self: end; color: var(--ink-soft); padding-block: 0.5rem; font-size: 0.85rem; }
.evidence-note { max-inline-size: 80ch; margin-block-start: 1rem; color: var(--ink-soft); font-size: 0.8rem; }
.section-layout { align-items: start; }
.section-layout .section-heading { grid-column: 1 / 5; }
.experience-list { grid-column: 5 / -1; list-style: none; }
.experience-list > li { display: grid; grid-template-columns: 7.75rem minmax(0, 1fr); gap: 1.5rem; padding-block: 1.25rem; border-block-start: 1px solid var(--line); }
.experience-list > li:first-child { padding-block-start: 0; border-block-start: none; }
.experience-list__period { display: flex; flex-wrap: wrap; align-content: start; gap: 0.2rem 0.4rem; color: var(--ink-soft); font-size: 0.8rem; font-variant-numeric: tabular-nums; line-height: 1.55; }
.experience-list__period time { white-space: nowrap; }
.experience-list__content > p:first-child { color: var(--cobalt-deep); font-size: 0.8rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; }
.experience-list__content h3 { margin-block: 0.35rem 0.65rem; font-size: 1.2rem; line-height: 1.35; letter-spacing: -0.015em; }
.experience-list__content > p { color: var(--ink-soft); font-size: 0.95rem; }
.chip-list { display: flex; flex-wrap: wrap; gap: 0.4rem 1rem; margin-block-start: 0.7rem; list-style: none; color: var(--ink-soft); font-size: 0.75rem; }
.experience-note { font-size: 0.85rem; }
.approach { background: var(--paper-raised); }
.principles-list { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 2.5rem; list-style: none; }
.principles-list__number { font-size: 0.8rem; color: var(--vermilion-deep); }
.principles-list h3 { font-size: 1.25rem; margin-block: 0.5rem; }
.principles-list p { color: var(--ink-soft); font-size: 1rem; }
.capabilities { margin-block-start: 2rem; border-block-start: 1px solid var(--line); padding-block-start: 0.5rem; }
.capabilities details > p { color: var(--ink-soft); margin-block: 0.5rem 1rem; max-inline-size: 60ch; }
.technology-index { display: flex; flex-wrap: wrap; gap: 0.75rem 1.5rem; margin-block-end: 1rem; list-style: none; font-size: 0.95rem; font-weight: 600; }
.contact { padding-block: var(--section-space); border-block-start: 3px solid var(--cobalt); }
.contact__layout { align-items: start; }
.contact__layout > header { grid-column: 1 / 6; }
.contact h2 { font-family: Georgia, 'Times New Roman', serif; font-size: clamp(2.2rem, 3.8vw, 3.5rem); font-weight: 500; line-height: 1.1; margin-block: 0.75rem 1.25rem; max-inline-size: 16ch; }
.contact__layout header > p:not(.eyebrow) { color: var(--ink-soft); max-inline-size: 43ch; }
.contact__availability { margin-block-start: 1rem; font-size: 0.9rem; }
.contact__actions { grid-column: 7 / -1; }
.contact__actions address { font-style: normal; }
.contact__email { display: flex; align-items: center; gap: 0.75rem; min-block-size: 3rem; margin-block: 0.5rem 0.75rem; font-size: clamp(1.3rem, 2.5vw, 2rem); font-weight: 600; line-height: 1.4; text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 0.2em; }
.contact__email:hover { color: var(--cobalt-deep); }
.contact__actions > p { font-size: 0.95rem; max-inline-size: 45ch; color: var(--ink-soft); }
.copy-email { border: 0; background: none; padding: 0; cursor: pointer; margin-block-start: 0.5rem; }
.copy-status { min-block-size: 1.6rem; font-size: 0.85rem !important; }
.contact__links { display: flex; flex-wrap: wrap; gap: 0 1.5rem; padding-block-start: 0.75rem; margin-block-start: 0.5rem; border-block-start: 1px solid var(--line); }
.contact__links .text-link { font-size: 0.85rem; }
.site-footer { padding-block: 1.25rem; border-block-start: 1px solid var(--line); color: var(--ink-soft); font-size: 0.8rem; }
.site-footer__inner p:first-child { grid-column: 1 / 8; }
.site-footer__inner p:last-child { grid-column: 8 / -1; justify-self: end; text-align: right; }

@media (max-width: 64rem) {
  .navigation__desktop { gap: 1rem; }
  .navigation__links { gap: 1rem; }
  .hero__copy { grid-column: 1 / 9; }
  .hero__sectors { grid-column: 9 / -1; padding-inline-start: 1.25rem; }
  .hero__career { font-size: 1.6rem; }
  .hero__career-description { margin-block-end: 1.25rem; }
  .hero__copy h1 { max-inline-size: 14ch; }
  .case-study__body { gap: 1.5rem; }
}
@media (max-width: 52rem) {
  .navigation__desktop { display: none; }
  .navigation__brand { grid-column: 1 / 9; }
  .navigation__mobile { display: block; }
  .hero__copy { grid-column: 1 / 8; }
  .hero__sectors { grid-column: 8 / -1; }
  .hero__copy h1 { font-size: 3.2rem; }
  .section-heading--inline { display: block; }
  .section-heading--inline > p { max-inline-size: 55ch; }
  .case-study__body { grid-template-columns: 1fr; gap: 1.5rem; }
  .case-study__copy { grid-template-columns: 1fr 1fr; gap: 1.5rem; }
  .case-study__copy .case-study__result { grid-column: 1 / -1; }
  .case-study__links { grid-column: 1 / -1; }
  .case-study__decisions { grid-template-columns: 1fr; gap: 1.25rem; }
  .section-layout .section-heading, .experience-list { grid-column: 1 / -1; }
  .section-layout .section-heading { margin-block-end: 0; }
  .section-heading h2 { max-inline-size: 25ch; }
  .principles-list { gap: 1.5rem; }
  .other-project { grid-template-columns: minmax(7rem, 1fr) minmax(0, 3fr); gap: 0.5rem 1.25rem; }
  .other-project > .text-link, .project-status { grid-column: 2; justify-self: start; }
}
@media (max-width: 38rem) {
  :root { --section-space: 3rem; }
  .navigation { min-block-size: 4.25rem; }
  .navigation__family { font-size: 0.95rem; }
  .navigation__brand { gap: 0.55rem; }
  .navigation__mobile summary { padding-inline: 0.5rem; font-size: 0.8rem; }
  .hero { padding-block: 2.25rem 2.5rem; }
  .hero__copy, .hero__sectors { grid-column: 1 / -1; }
  .hero__layout { row-gap: 1.75rem; }
  .hero__copy h1 { font-size: clamp(2.5rem, 10.7vw, 3.6rem); max-inline-size: 14ch; margin-block: 1rem; }
  .hero__subtitle { font-size: 1.25rem; }
  .hero__description { font-size: 1rem; }
  .hero__actions { margin-block-start: 1.25rem; gap: 0.6rem; }
  .action-link { flex: 1 1 auto; padding-inline: 0.8rem; font-size: 0.85rem; }
  .hero__contact { font-size: 0.8rem; }
  .hero__sectors { padding-inline-start: 0; border-inline-start: 0; border-block-start: 1px solid var(--line); padding-block-start: 1.25rem; }
  .hero__career { font-size: 1.5rem; }
  .hero__career-description { margin-block: 0.5rem 1rem; font-size: 0.9rem; }
  .hero__sectors-list { font-size: 0.85rem; gap: 0.2rem 0.75rem; }
  .section-heading h2 { font-size: 2rem; }
  .section-heading--inline > p { margin-block-start: 0.75rem; }
  .case-study { padding-block-start: 1.5rem; }
  .case-study__heading { margin-block-end: 1.25rem; }
  .case-study__heading h3 { display: block; font-size: 2rem; }
  .case-study__heading h3 span { display: block; margin-block-start: 0.5rem; font-size: 1rem; }
  .case-study__copy { grid-template-columns: 1fr; gap: 1.1rem; }
  .case-study__image-link > span { font-size: 0.65rem; }
  .case-study__disclosure { margin-block-start: 1rem; }
  .case-study__disclosure summary { font-size: 0.9rem; }
  .other-project { grid-template-columns: 1fr; gap: 0.75rem; }
  .other-project > .text-link, .project-status { grid-column: 1; }
  .other-projects > h3 { font-size: 1.3rem; }
  .experience-list > li { grid-template-columns: 1fr; gap: 0.5rem; }
  .experience-list__period { gap: 0.5rem; }
  .principles-list { grid-template-columns: 1fr; gap: 1.75rem; }
  .principles-list li { display: grid; grid-template-columns: 1.75rem 1fr; gap: 0.25rem 0.75rem; }
  .principles-list__number { grid-row: 1 / 3; padding-block-start: 0.25rem; }
  .principles-list h3 { margin: 0; font-size: 1.2rem; }
  .principles-list p { grid-column: 2; }
  .contact__layout > header, .contact__actions { grid-column: 1 / -1; }
  .contact h2 { max-inline-size: 15ch; font-size: 2.5rem; }
  .contact__email { font-size: clamp(1.25rem, 6vw, 1.7rem); gap: 0.5rem; }
  .site-footer__inner p:first-child, .site-footer__inner p:last-child { grid-column: 1 / -1; justify-self: start; text-align: start; }
  .site-footer__inner { row-gap: 0.25rem; }
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation: none !important; transition: none !important; }
}
@media (forced-colors: active) {
  .action-link, .language-link, .navigation__mobile summary, .case-study__image-link { border: 1px solid ButtonText; }
  .case-study__result { border-color: CanvasText; }
  .text-link, .contact__email { color: LinkText; }
}
